
CREATE TABLE upload_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES users(id),batch_id uuid REFERENCES batches(id),purpose text NOT NULL CHECK(purpose IN ('resource','attachment','gallery','profile','event','batch')),storage_key text NOT NULL UNIQUE,mime_type text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0),file_name text NOT NULL,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','UPLOADED','CONSUMED')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),module_id uuid,created_by uuid NOT NULL REFERENCES users(id),updated_by uuid REFERENCES users(id),title text NOT NULL,body text NOT NULL,priority text NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('NORMAL','IMPORTANT','URGENT')),pinned boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),published_at timestamptz,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id),FOREIGN KEY(batch_id,module_id) REFERENCES modules(batch_id,id));
CREATE INDEX announcements_list ON announcements(batch_id,status,published_at DESC,id DESC);
CREATE TABLE announcement_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,announcement_id uuid NOT NULL,file_name text NOT NULL,storage_key text NOT NULL UNIQUE,mime_type text NOT NULL CHECK(mime_type='application/pdf'),size_bytes bigint NOT NULL CHECK(size_bytes>0),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(batch_id,announcement_id) REFERENCES announcements(batch_id,id));
